struct json_value_s *json_parse(const void *src, size_t src_size) {
  return json_parse_ex(src, src_size, json_parse_flags_default, 0, 0, 0);
}

struct json_value_s *json_extract_value(const struct json_value_s *value) {
  return json_extract_value_ex(value, 0, 0);
}

struct json_value_s *json_extract_value_ex(const struct json_value_s *value, void *(*alloc_func_ptr)(void *, size_t), void *user_data) {
  void *allocation;
  struct json_extract_result_s result;
  struct json_extract_state_s state;
  size_t total_size;
  if (0 == value) {
    return 0;
  }
  result = json_extract_get_value_size(value);
  total_size = result.dom_size + result.data_size;
  if (0 == alloc_func_ptr) {
    allocation = malloc(total_size);
  } else {
    allocation = alloc_func_ptr(user_data, total_size);
  }
  state.dom = (char *)allocation;
  state.data = state.dom + result.dom_size;
  json_extract_copy_value(&state, value);
  return (struct json_value_s *)allocation;
}

void *json_write_minified(const struct json_value_s *value, size_t *out_size) {
  size_t size = 0;
  char *data = 0;
  char *data_end = 0;
  if (0 == value) {
    return 0;
  }
  if (json_write_minified_get_value_size(value, &size)) {
    return 0;
  }
  size += 1;
  data = (char *)malloc(size);
  if (0 == data) {
    return 0;
  }
  data_end = json_write_minified_value(value, data);
  if (0 == data_end) {
    free(data);
    return 0;
  }
  *data_end = '\0';
  if (0 != out_size) {
    *out_size = size;
  }
  return data;
}

void *json_write_pretty(const struct json_value_s *value, const char *indent, const char *newline, size_t *out_size) {
  size_t size = 0;
  size_t indent_size = 0;
  size_t newline_size = 0;
  char *data = 0;
  char *data_end = 0;
  if (0 == value) {
    return 0;
  }
  if (0 == indent) {
    indent = "  ";
  }
  if (0 == newline) {
    newline = "\n";
  }
  while ('\0' != indent[indent_size]) {
    ++indent_size;
  }
  while ('\0' != newline[newline_size]) {
    ++newline_size;
  }
  if (json_write_pretty_get_value_size(value, 0, indent_size, newline_size, &size)) {
    return 0;
  }
  size += 1;
  data = (char *)malloc(size);
  if (0 == data) {
    return 0;
  }
  data_end = json_write_pretty_value(value, 0, indent, newline, data);
  if (0 == data_end) {
    free(data);
    return 0;
  }
  *data_end = '\0';
  if (0 != out_size) {
    *out_size = size;
  }
  return data;
}

struct json_string_s *json_value_as_string(struct json_value_s *const value) {
  if (value->type != json_type_string) {
    return 0;
  }
  return (struct json_string_s *)value->payload;
}

struct json_number_s *json_value_as_number(struct json_value_s *const value) {
