int json_hexadecimal_digit(const char c) {
  if ('0' <= c && c <= '9') {
    return c - '0';
  }
  if ('a' <= c && c <= 'f') {
    return c - 'a' + 10;
  }
  if ('A' <= c && c <= 'F') {
    return c - 'A' + 10;
  }
  return -1;
}

int json_hexadecimal_value(const char *c, const unsigned long size, unsigned long *result) {
  const char *p;
  int digit;
  if (size > sizeof(unsigned long) * 2) {
    return 0;
  }
  *result = 0;
  for (p = c; (unsigned long)(p - c) < size; ++p) {
    *result <<= 4;
    digit = json_hexadecimal_digit(*p);
    if (digit < 0 || digit > 15) {
      return 0;
    }
    *result |= (unsigned char)digit;
  }
  return 1;
}

int json_skip_whitespace(struct json_parse_state_s *state) {
  size_t offset = state->offset;
  const size_t size = state->size;
  const char *const src = state->src;
  if (offset >= state->size) {
    return 0;
  }
  switch (src[offset]) {
  default: return 0;
  case ' ': case '\r': case '\t': case '\n': break;
  }
  do {
    switch (src[offset]) {
    default: state->offset = offset;
      return 1;
    case ' ': case '\r': case '\t': break;
    case '\n': state->line_no++;
      state->line_offset = offset;
      break;
    }
    offset++;
  } while (offset < size);
  state->offset = offset;
  return 1;
}

int json_skip_c_style_comments(struct json_parse_state_s *state) {
  if ((state->offset + 2) > state->size) {
    return 0;
  }
  if ('/' == state->src[state->offset]) {
    if ('/' == state->src[state->offset + 1]) {
      state->offset++;
      state->offset++;
      while (state->offset < state->size) {
        switch (state->src[state->offset]) {
        default: state->offset++;
          break;
        case '\n': state->offset++;
          state->line_no++;
          state->line_offset = state->offset;
          return 1;
        }
      }
      return 1;
    } else if ('*' == state->src[state->offset + 1]) {
      state->offset++;
      state->offset++;
      while (state->offset + 1 < state->size) {
        if (('*' == state->src[state->offset]) && ('/' == state->src[state->offset + 1])) {
          state->offset += 2;
          return 1;
        } else if ('\n' == state->src[state->offset]) {
          state->line_no++;
          state->line_offset = state->offset;
        }
        state->offset++;
      }
      return 1;
    }
  }
  return 0;
}

int json_skip_all_skippables(struct json_parse_state_s *state) {
  int did_consume = 0;
  const size_t size = state->size;
  if (json_parse_flags_allow_c_style_comments & state->flags_bitset) {
    do {
      if (state->offset == size) {
        state->error = json_parse_error_premature_end_of_buffer;
        return 1;
      }
      did_consume = json_skip_whitespace(state);
      if (state->offset >= size) {
        state->error = json_parse_error_premature_end_of_buffer;
        return 1;
      }
      did_consume |= json_skip_c_style_comments(state);
    } while (0 != did_consume);
  } else {
    do {
      if (state->offset == size) {
        state->error = json_parse_error_premature_end_of_buffer;
        return 1;
      }
      did_consume = json_skip_whitespace(state);
    } while (0 != did_consume);
  }
  if (state->offset == size) {
    state->error = json_parse_error_premature_end_of_buffer;
    return 1;
  }
  return 0;
}

int json_get_value_size(struct json_parse_state_s *state, int is_global_object) {
  const size_t flags_bitset = state->flags_bitset;
  const char *const src = state->src;
  size_t offset;
  const size_t size = state->size;
  if (json_parse_flags_allow_location_information & flags_bitset) {
    state->dom_size += sizeof(struct json_value_ex_s);
  } else {
    state->dom_size += sizeof(struct json_value_s);
  }
  if (is_global_object) {
    return json_get_object_size(state, 1);
  } else {
    if (json_skip_all_skippables(state)) {
      state->error = json_parse_error_premature_end_of_buffer;
      return 1;
    }
    offset = state->offset;
    switch (src[offset]) {
    case '"': return json_get_string_size(state, 0);
    case '\'': if (json_parse_flags_allow_single_quoted_strings & flags_bitset) {
        return json_get_string_size(state, 0);
      } else {
        state->error = json_parse_error_invalid_value;
        return 1;
      }
    case '{': return json_get_object_size(state, 0);
    case '[': return json_get_array_size(state);
    case '-': case '0': case '1': case '2': case '3': case '4': case '5': case '6': case '7': case '8': case '9': return json_get_number_size(state);
    case '+': if (json_parse_flags_allow_leading_plus_sign & flags_bitset) {
        return json_get_number_size(state);
      } else {
        state->error = json_parse_error_invalid_number_format;
        return 1;
      }
    case '.': if (json_parse_flags_allow_leading_or_trailing_decimal_point & flags_bitset) {
        return json_get_number_size(state);
      } else {
        state->error = json_parse_error_invalid_number_format;
        return 1;
      }
    default: if ((offset + 4) <= size && 't' == src[offset + 0] && 'r' == src[offset + 1] && 'u' == src[offset + 2] && 'e' == src[offset + 3]) {
        state->offset += 4;
        return 0;
      } else if ((offset + 5) <= size && 'f' == src[offset + 0] && 'a' == src[offset + 1] && 'l' == src[offset + 2] && 's' == src[offset + 3] && 'e' == src[offset + 4]) {
        state->offset += 5;
        return 0;
      } else if ((offset + 4) <= size && 'n' == state->src[offset + 0] && 'u' == state->src[offset + 1] && 'l' == state->src[offset + 2] && 'l' == state->src[offset + 3]) {
        state->offset += 4;
        return 0;
      } else if ((json_parse_flags_allow_inf_and_nan & flags_bitset) && (offset + 3) <= size && 'N' == src[offset + 0] && 'a' == src[offset + 1] && 'N' == src[offset + 2]) {
        return json_get_number_size(state);
      } else if ((json_parse_flags_allow_inf_and_nan & flags_bitset) && (offset + 8) <= size && 'I' == src[offset + 0] && 'n' == src[offset + 1] && 'f' == src[offset + 2] && 'i' == src[offset + 3] && 'n' == src[offset + 4] && 'i' == src[offset + 5] && 't' == src[offset + 6] && 'y' == src[offset + 7]) {
        return json_get_number_size(state);
      }
      state->error = json_parse_error_invalid_value;
      return 1;
    }
  }
}

int json_get_string_size(struct json_parse_state_s *state, size_t is_key) {
  size_t offset = state->offset;
  const size_t size = state->size;
  size_t data_size = 0;
  const char *const src = state->src;
  const int is_single_quote = '\'' == src[offset];
  const char quote_to_use = is_single_quote ? '\'' : '"';
  const size_t flags_bitset = state->flags_bitset;
  unsigned long codepoint;
  unsigned long high_surrogate = 0;
  if ((json_parse_flags_allow_location_information & flags_bitset) != 0 && is_key != 0) {
    state->dom_size += sizeof(struct json_string_ex_s);
  } else {
    state->dom_size += sizeof(struct json_string_s);
  }
  if ('"' != src[offset]) {
    if (!((json_parse_flags_allow_single_quoted_strings & flags_bitset) && is_single_quote)) {
      state->error = json_parse_error_expected_opening_quote;
      state->offset = offset;
      return 1;
    }
  }
  offset++;
  while ((offset < size) && (quote_to_use != src[offset])) {
    data_size++;
    switch (src[offset]) {
    default: break;
    case '\0': case '\t': state->error = json_parse_error_invalid_string;
      state->offset = offset;
      return 1;
    }
    if ('\\' == src[offset]) {
      offset++;
      if (offset == size) {
        state->error = json_parse_error_premature_end_of_buffer;
        state->offset = offset;
        return 1;
      }
      switch (src[offset]) {
      default: state->error = json_parse_error_invalid_string_escape_sequence;
        state->offset = offset;
        return 1;
      case '"': case '\\': case '/': case 'b': case 'f': case 'n': case 'r': case 't': offset++;
        break;
      case 'u': if (!(offset + 5 < size)) {
          state->error = json_parse_error_invalid_string_escape_sequence;
          state->offset = offset;
          return 1;
        }
        codepoint = 0;
        if (!json_hexadecimal_value(&src[offset + 1], 4, &codepoint)) {
          state->error = json_parse_error_invalid_string_escape_sequence;
          state->offset = offset;
          return 1;
        }
        if (high_surrogate != 0) {
          if (codepoint >= 0xdc00 && codepoint <= 0xdfff) {
            data_size += 3;
            high_surrogate = 0;
          } else {
            state->error = json_parse_error_invalid_string_escape_sequence;
            state->offset = offset;
            return 1;
          }
        } else if (codepoint <= 0x7f) {
          data_size += 0;
        } else if (codepoint <= 0x7ff) {
          data_size += 1;
        } else if (codepoint >= 0xd800 && codepoint <= 0xdbff) {
          if (offset + 11 > size || '\\' != src[offset + 5] || 'u' != src[offset + 6]) {
            state->error = json_parse_error_invalid_string_escape_sequence;
            state->offset = offset;
            return 1;
          }
          high_surrogate = codepoint;
        } else if (codepoint >= 0xd800 && codepoint <= 0xdfff) {
          state->error = json_parse_error_invalid_string_escape_sequence;
          state->offset = offset;
          return 1;
        } else {
          data_size += 2;
        }
        offset += 5;
        break;
      }
    } else if (('\r' == src[offset]) || ('\n' == src[offset])) {
      if (!(json_parse_flags_allow_multi_line_strings & flags_bitset)) {
        state->error = json_parse_error_invalid_string_escape_sequence;
        state->offset = offset;
        return 1;
      }
      offset++;
    } else {
      offset++;
    }
  }
  if (offset == size) {
    state->error = json_parse_error_premature_end_of_buffer;
    state->offset = offset - 1;
    return 1;
  }
  offset++;
  state->data_size += data_size;
  state->data_size++;
  state->offset = offset;
  return 0;
}

int is_valid_unquoted_key_char(const char c) {
  return (('0' <= c && c <= '9') || ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z') || ('_' == c));
}

int json_get_key_size(struct json_parse_state_s *state) {
  const size_t flags_bitset = state->flags_bitset;
  if (json_parse_flags_allow_unquoted_keys & flags_bitset) {
    size_t offset = state->offset;
    const size_t size = state->size;
    const char *const src = state->src;
    size_t data_size = state->data_size;
    if ('"' == src[offset]) {
      return json_get_string_size(state, 1);
    } else if ((json_parse_flags_allow_single_quoted_strings & flags_bitset) && ('\'' == src[offset])) {
      return json_get_string_size(state, 1);
    } else {
      while ((offset < size) && is_valid_unquoted_key_char(src[offset])) {
        offset++;
        data_size++;
      }
      data_size++;
      if (json_parse_flags_allow_location_information & flags_bitset) {
        state->dom_size += sizeof(struct json_string_ex_s);
      } else {
        state->dom_size += sizeof(struct json_string_s);
      }
      state->offset = offset;
      state->data_size = data_size;
      return 0;
    }
  } else {
    return json_get_string_size(state, 1);
  }
}

int json_get_object_size(struct json_parse_state_s *state, int is_global_object) {
  const size_t flags_bitset = state->flags_bitset;
  const char *const src = state->src;
  const size_t size = state->size;
  size_t elements = 0;
  int allow_comma = 0;
  int found_closing_brace = 0;
  if (is_global_object) {
    if (!json_skip_all_skippables(state) && '{' == state->src[state->offset]) {
      is_global_object = 0;
    }
  }
  if (!is_global_object) {
    if ('{' != src[state->offset]) {
      state->error = json_parse_error_unknown;
      return 1;
    }
    state->offset++;
  }
  state->dom_size += sizeof(struct json_object_s);
  if ((state->offset == size) && !is_global_object) {
    state->error = json_parse_error_premature_end_of_buffer;
    return 1;
  }
  do {
    if (!is_global_object) {
      if (json_skip_all_skippables(state)) {
        state->error = json_parse_error_premature_end_of_buffer;
        return 1;
      }
      if ('}' == src[state->offset]) {
        state->offset++;
        found_closing_brace = 1;
        break;
      }
    } else {
      if (json_skip_all_skippables(state)) {
        break;
      }
    }
    if (allow_comma) {
      if (',' == src[state->offset]) {
        state->offset++;
        allow_comma = 0;
      } else if (json_parse_flags_allow_no_commas & flags_bitset) {
        allow_comma = 0;
      } else {
        state->error = json_parse_error_expected_comma_or_closing_bracket;
        return 1;
      }
      if (json_parse_flags_allow_trailing_comma & flags_bitset) {
        continue;
      } else {
        if (json_skip_all_skippables(state)) {
          state->error = json_parse_error_premature_end_of_buffer;
          return 1;
        }
      }
    }
    if (json_get_key_size(state)) {
      state->error = json_parse_error_invalid_string;
      return 1;
    }
    if (json_skip_all_skippables(state)) {
      state->error = json_parse_error_premature_end_of_buffer;
      return 1;
    }
    if (json_parse_flags_allow_equals_in_object & flags_bitset) {
      const char current = src[state->offset];
      if ((':' != current) && ('=' != current)) {
        state->error = json_parse_error_expected_colon;
        return 1;
      }
    } else {
      if (':' != src[state->offset]) {
        state->error = json_parse_error_expected_colon;
        return 1;
      }
    }
    state->offset++;
    if (json_skip_all_skippables(state)) {
      state->error = json_parse_error_premature_end_of_buffer;
      return 1;
    }
    if (json_get_value_size(state, 0)) {
      return 1;
    }
    elements++;
    allow_comma = 1;
  } while (state->offset < size);
  if ((state->offset == size) && !is_global_object && !found_closing_brace) {
    state->error = json_parse_error_premature_end_of_buffer;
    return 1;
  }
  state->dom_size += sizeof(struct json_object_element_s) * elements;
  return 0;
}

int json_get_array_size(struct json_parse_state_s *state) {
  const size_t flags_bitset = state->flags_bitset;
  size_t elements = 0;
  int allow_comma = 0;
  const char *const src = state->src;
  const size_t size = state->size;
  if ('[' != src[state->offset]) {
    state->error = json_parse_error_unknown;
    return 1;
  }
  state->offset++;
  state->dom_size += sizeof(struct json_array_s);
  while (state->offset < size) {
    if (json_skip_all_skippables(state)) {
      state->error = json_parse_error_premature_end_of_buffer;
      return 1;
    }
    if (']' == src[state->offset]) {
      state->offset++;
      state->dom_size += sizeof(struct json_array_element_s) * elements;
      return 0;
    }
    if (allow_comma) {
      if (',' == src[state->offset]) {
        state->offset++;
        allow_comma = 0;
      } else if (!(json_parse_flags_allow_no_commas & flags_bitset)) {
        state->error = json_parse_error_expected_comma_or_closing_bracket;
        return 1;
      }
      if (json_parse_flags_allow_trailing_comma & flags_bitset) {
        allow_comma = 0;
        continue;
      } else {
        if (json_skip_all_skippables(state)) {
          state->error = json_parse_error_premature_end_of_buffer;
          return 1;
        }
      }
